arguments.command:
cd /tmp/sv-21ff3f6d348842deae77b11f365ac78a && \
# Those offsets are too large. Let me get all dynamic function symbols and find nearest
aarch64-linux-gnu-nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk '$2~/[TtWw]/' | sort | awk -v t1="0x2f4b20" -v t2="0x2f4c84" '
BEGIN {target1=strtonum(t1); target2=strtonum(t2)}
{
  a=strtonum("0x"$1)
  if(a<=target1){s1=$3; o1=target1-a}
  if(a<=target2){s2=$3; o2=target2-a}
}
END {
  printf "0x2f4b20: %s + 0x%x\n", s1, o1
  printf "0x2f4c84: %s + 0x%x\n", s2, o2
}'

